import{c as e,Z as a,Q as r,j as s,m as n,o as l}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"鹿鸣","description":"","frontmatter":{"title":"鹿鸣","author":"佚名","dynasty":"先秦"},"headers":[],"relativePath":"books/shici/shijing/6.md","filePath":"books/shici/shijing/6.md"}'),h={name:"books/shici/shijing/6.md"};function c(u,i,d,_,m,p){const o=a("PoemAuthor"),t=a("PoemNav");return r(),s("div",null,[i[0]||(i[0]=n('<h1 id="鹿鸣" tabindex="-1">鹿鸣 <a class="header-anchor" href="#鹿鸣" aria-label="Permalink to &quot;鹿鸣&quot;">​</a></h1><p><strong>《诗经·小雅》</strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>呦呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙。吹笙鼓簧，承筐是将。人之好我，示我周行。 呦呦鹿鸣，食野之蒿。我有嘉宾，德音孔昭。视民不恌，君子是则是效。我有旨酒，嘉宾式燕以敖。 呦呦鹿鸣，食野之芩。我有嘉宾，鼓瑟鼓琴。鼓瑟鼓琴，和乐且湛。我有旨酒，以燕乐嘉宾之心。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>呦呦：鹿鸣声</li><li>苹：艾蒿，一种植物</li><li>嘉宾：尊贵的客人</li><li>瑟：古代弦乐器</li><li>笙：古代管乐器</li><li>簧：笙中的簧片</li><li>承筐：捧着礼品筐</li><li>将：献上</li><li>好：善待</li><li>周行：大道，指正确的方法</li><li>蒿：青蒿</li><li>德音：美好的声誉</li><li>孔昭：非常显著</li><li>视：同&quot;示&quot;</li><li>恌：同&quot;佻&quot;，轻薄</li><li>则：法则，榜样</li><li>效：效仿</li><li>旨酒：美酒</li><li>式：语气词</li><li>燕：同&quot;宴&quot;，宴饮</li><li>敖：同&quot;遨&quot;，游乐</li><li>芩：黄芩，一种植物</li><li>湛：深厚，指欢乐深厚</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>鹿群呦呦鸣叫，在原野上吃着艾蒿。我有尊贵的宾客，弹瑟吹笙来欢迎。吹起笙来奏起簧，捧着礼筐献上礼品。人们对我很友善，指示我正确的方向。 鹿群呦呦鸣叫，在原野上吃着青蒿。我有尊贵的宾客，品德高尚声誉好。示范人们不轻薄，君子以此为榜样。我有美酒来款待，宾客宴饮多欢畅。 鹿群呦呦鸣叫，在原野上吃着黄芩。我有尊贵的宾客，弹瑟弹琴来欢迎。弹起瑟来奏起琴，和谐欢乐情意深。我有美酒来款待，以此娱乐宾客心。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>《鹿鸣》是《诗经·小雅》的首篇，是一首宴飨诗，描写贵族宴会宾客的场景。全诗三章，以&quot;呦呦鹿鸣，食野之苹&quot;起兴，以鹿群和谐共处比喻宾主之间的融洽关系。每章都写主人以音乐、美酒款待宾客，表达了对宾客的尊重和欢迎之情。此诗是周代贵族宴会的乐歌，后来成为科举时代&quot;鹿鸣宴&quot;的典故来源，寓意招贤纳士、君臣和睦。全诗节奏明快，气氛热烈，表现了古代礼仪之邦的好客之风和和谐的人际关系。</p>',10)),l(o,{name:"《诗经》",years:"西周初年至春秋中叶",desc:"中国最早的诗歌总集，收录了西周初年至春秋中叶（前11世纪至前6世纪）的诗歌305篇，分为“风”“雅”“颂”三部分。《诗经》内容丰富，反映了周代社会生活的方方面面，是中国现实主义文学的源头。",link:"/books/shici/shijing","is-shijing":""}),l(t)])}const f=e(h,[["render",c]]);export{b as __pageData,f as default};
